/** What a run proved: the engine's verification report, the outcome summary behind it, and the artifacts it captured, bytes included. */
export class EvidenceResource {
  readonly #transport: Transport

  constructor(transport: Transport) {
    this.#transport = transport
  }

  /**
   * Download an artifact's bytes
   * The stored bytes of one artifact listed by the run-artifacts endpoint, served with the recorded image content type (`nosniff`, never inline active content). Authenticated like every other call: the bytes are workspace-scoped, so a report that links here on a public repository leaks nothing to a reader without a key. 404 when the id is unknown to the key’s workspace, and separately when the metadata row survives but its bytes are gone from the blob backend.
   * `GET /api/v1/artifacts/{artifactId}/blob` — operation `getPublicArtifactBlob`.
   */
  downloadArtifact(artifactId: string, options: RequestOptions = {}): Promise<Uint8Array> {
    return this.#transport.bytes({
      method: 'GET',
      path: `/api/v1/artifacts/${encodePathSegment(artifactId)}/blob`,
      options,
    })
  }

  /**
   * Get a run's outcome summary
   * What the run changed and what backs that up, in product language, for a reader who will not open the diff: the run’s disposition, the pull requests it opened, requirement coverage joined to the service’s `spec/`, the tester’s verdict and concerns, the views it captured, the throwaway environments it stood up (`state: "live"` is the only one worth opening, and only while its `expiresAt` is still ahead; every other row still carries its URL), and the machine checks that ran. The same reduction the app’s outcome card renders, over the same evidence the verification report is built from, so the two cannot state different totals for one run. Nothing here is asserted by a model: every count is derived from recorded verdicts. Prefer the verification report when you need a reviewer’s full bundle; prefer this when you need to say what shipped. Sections state `reported` or `absent` with a machine-readable gap code, and `truncations` names any list the response had to bound.
   * `GET /api/v1/runs/{runId}/outcome` — operation `getPublicRunOutcome`.
   */
  getOutcome(runId: string, options: RequestOptions = {}): Promise<GetPublicRunOutcomeResponse> {
    return this.#transport.request<GetPublicRunOutcomeResponse>({
      method: 'GET',
      path: `/api/v1/runs/${encodePathSegment(runId)}/outcome`,
      options,
    })
  }

  /**
   * Get a run's verification report
   * The engine’s bundle of CAPTURED FACTS about a run: the CI gate’s verdict and failing checks, the platform’s own run of the service’s lint/test/build commands (with the failing output), the red-then-green reproduction proof for a bugfix, the tester’s structured report, requirement coverage, the throwaway-environment lifecycle, judge verdicts and the merge decision. Byte-for-byte the JSON block the pull-request body carries, composed on read, so it also answers for a run that never opened a pull request. Each section states `reported` or `absent` with a note, so a step that did not run never looks like a step that found nothing.
   * `GET /api/v1/runs/{runId}/report` — operation `getPublicRunReport`.
   */
  getReport(runId: string, options: RequestOptions = {}): Promise<PrVerificationReport> {
    return this.#transport.request<PrVerificationReport>({
      method: 'GET',
      path: `/api/v1/runs/${encodePathSegment(runId)}/report`,
      options,
    })
  }

  /**
   * List a run's captured artifacts
   * The binary artifacts the run captured (UI screenshots) plus the reference images they were reviewed against: id, kind, view, content type, exact byte size and content hash. Unpaged: the capture path caps how many one run may store, so the response size is bounded before the request. Fetch the bytes with the blob endpoint.
   * `GET /api/v1/runs/{runId}/artifacts` — operation `listPublicRunArtifacts`.
   */
  listArtifacts(runId: string, options: RequestOptions = {}): Promise<PublicRunArtifactList> {
    return this.#transport.request<PublicRunArtifactList>({
      method: 'GET',
      path: `/api/v1/runs/${encodePathSegment(runId)}/artifacts`,
      options,
    })
  }
}

/** The evidence behind the auto-merge policy: what kind of change each merged run made, what the merger scored it, what happened to the pull request, and how much review a human actually spent, plus the per-class rollups that justify widening a rule. Reading takes a `read` key and recording an effort tag a `write` one: neither merges anything. */
export class MergeRecordsResource {
  readonly #transport: Transport

  constructor(transport: Transport) {
    this.#transport = transport
  }

  /**
   * Get one merge record
   * The same record addressed by its own id, for a caller that holds one without the run: the id a `merge_tag_request` notification carries on its payload, for instance. Scoped to the calling key’s workspace.
   * `GET /api/v1/merge-records/{recordId}` — operation `getPublicMergeRecord`.
   */
  get(recordId: string, options: RequestOptions = {}): Promise<GetPublicMergeRecordResponse> {
    return this.#transport.request<GetPublicMergeRecordResponse>({
      method: 'GET',
      path: `/api/v1/merge-records/${encodePathSegment(recordId)}`,
      options,
    })
  }

  /**
   * Get the merge decision a run left behind
   * What kind of change the run’s pull request made (a change class derived on the backend from the changed-file list, never from an agent’s opinion), what the merger scored it, which merge-threshold preset the decision was compared against, what ultimately happened to the pull request, and how much review a human spent if anybody has tagged it. The entry point of the merge-evidence loop for a caller holding a run id: it also hands back the `recordId` the effort-tag route takes. A run whose pipeline had no `merger` step made no merge decision and answers `404` with `details.reason: "no_merge_record"`, distinct from the `"run_not_found"` a run this key cannot read gets.
   * `GET /api/v1/runs/{runId}/merge-record` — operation `getPublicRunMergeRecord`.
   */
  getForRun(runId: string, options: RequestOptions = {}): Promise<GetPublicMergeRecordResponse> {
    return this.#transport.request<GetPublicMergeRecordResponse>({
      method: 'GET',
      path: `/api/v1/runs/${encodePathSegment(runId)}/merge-record`,
      options,
    })
  }

  /**
   * List the per-change-class merge rollups
   * Every change class’s accumulated track record for the workspace, as one aggregate: how many records it holds, how many landed and by which route (auto-merged, merged through the app, merged directly on the provider), how many were rejected or are still awaiting review, and the distribution of reviewer-effort tags. This is the evidence that justifies widening a per-class auto-merge rule; nothing widens one automatically. A class with no records is present as zeros rather than absent, so "nothing has landed here yet" never reads as a class the response left out. `unknown` is a real class (no changed-file list was available) and never matches a per-class rule.
   * `GET /api/v1/merge-records/rollups` — operation `listPublicMergeClassRollups`.
   */
  listRollups(options: RequestOptions = {}): Promise<ListPublicMergeClassRollupsResponse> {
    return this.#transport.request<ListPublicMergeClassRollupsResponse>({
      method: 'GET',
      path: `/api/v1/merge-records/rollups`,
      options,
    })
  }

  /**
   * Tag the reviewer effort a merge took
   * Record how much review a landed pull request actually needed (`none` for zero blocking comments, `minor` for a nit pass, `major` for real rework), or `null` to clear the tag. This is the ground truth the auto-merge score thresholds are trying to approximate, and it is never mandatory: an untagged merge records a null tag and nothing downstream breaks. A `write` key, not an `admin` one: the pull request already landed, so tagging it merges nothing. Idempotent, and orthogonal to the decision, so a record can be tagged whenever the effort becomes known, before or after the `act` that merged it.
   * `POST /api/v1/merge-records/{recordId}/effort` — operation `tagPublicMergeReviewEffort`.
   */
  tagEffort(recordId: string, body: TagPublicMergeReviewEffortRequest, options: RequestOptions = {}): Promise<GetPublicMergeRecordResponse> {
    return this.#transport.request<GetPublicMergeRecordResponse>({
      method: 'POST',
      path: `/api/v1/merge-records/${encodePathSegment(recordId)}/effort`,
      body,
      options,
    })
  }
}

/** The workspace's own API keys: provision one headlessly, list them, revoke one (and what it minted). */
export class KeysResource {
  readonly #transport: Transport

  constructor(transport: Transport) {
    this.#transport = transport
  }

  /**
   * Provision an API key
   * Mint a key for the calling key’s own workspace and return its raw secret EXACTLY ONCE, so store it now: it is not recoverable. Omitting `scope` mints a `write` key. `admin` cannot be minted here: a key provisioned over the API can never itself provision, which keeps the chain one link long. Requires an `admin`-scope key.
   * `POST /api/v1/keys` — operation `createPublicKey`.
   */
  create(body: CreateHeadlessPublicApiKey, options: RequestOptions = {}): Promise<CreatedPublicApiKey> {
    return this.#transport.request<CreatedPublicApiKey>({
      method: 'POST',
      path: `/api/v1/keys`,
      body,
      options,
    })
  }

  /**
   * List the workspace's API keys
   * The live (non-revoked) keys for the calling key’s workspace, metadata only; a secret is never readable back. `createdByKeyId` names the key that provisioned a key headlessly; `createdByUserId` names the person who minted one in the app.
   * `GET /api/v1/keys` — operation `listPublicKeys`.
   */
  list(options: RequestOptions = {}): Promise<PublicApiKeyList> {
    return this.#transport.request<PublicApiKeyList>({
      method: 'GET',
      path: `/api/v1/keys`,
      options,
    })
  }

  /**
   * Revoke an API key
   * Revoke a key AND every key it minted, so a leaked provisioning key cannot outlive its own revocation through the credentials it left behind. Idempotent, and it may name the calling key. Requires an `admin`-scope key.
   * `DELETE /api/v1/keys/{keyId}` — operation `revokePublicKey`.
   */
  revoke(keyId: string, options: RequestOptions = {}): Promise<void> {
    return this.#transport.requestNoContent({
      method: 'DELETE',
      path: `/api/v1/keys/${encodePathSegment(keyId)}`,
      options,
    })
  }
}

/**
 * The resource clients a `CatFactoryClient` exposes, one per tag of the published OpenAPI surface.
 *
 * Generated and INHERITED by the client rather than re-listed on it: a resource group added to the
 * SDK surface table would otherwise generate, compile, and simply not be reachable from the client
 * anyone actually constructs. (A declaration-merged interface would do the same job, but TypeScript
 * cannot see that such properties are initialised — so a real base class it is.)
 */
export abstract class CatFactoryResources {
  /** Headless jobs (a public, inline pipeline run against a brief): start, poll or stream one. */
  readonly jobs: JobsResource
  /** The workspace's board services, the frames tasks are created under: list them, create one (optionally backed by a repository), or patch one, including declaring where the manifests for its per-run environments are read from. */
  readonly services: ServicesResource
  /** A service's in-repo specification: the structured requirement tree (modules → feature groups → requirements, with their acceptance criteria and domain rules), the Gherkin rendered from it, and the branch and commit the read describes. Read-only; the requirement ids are the join key onto a run's report and outcome. */
  readonly spec: SpecResource
  /** The repositories this workspace can back a service with, and which service each already backs (the discovery half of service creation); the ones its connection could reach but has not adopted yet, and adopting one by name; plus creating a brand-new one, where a bootstrap writes the repository with an agent and reports the board service it materialises. */
  readonly repos: ReposResource
  /** A board task's whole lifecycle: create, edit, start, stop, retry, watch, delete, plus the two relationships that outlive a create: the tasks it waits for, and the requirements documents it is built against. */
  readonly tasks: TasksResource
  /** The pipelines a task can be started with, and whether each is headless-startable. */
  readonly pipelines: PipelinesResource
  /** What a task can be created AS in this workspace (the built-in kinds plus the operations the deployment registered), and the fields each one accepts. */
  readonly taskTypes: TaskTypesResource
  /** The workspace's human-actionable inbox: list, act on, or dismiss a run tail. */
  readonly notifications: NotificationsResource
  /** The cluster this workspace provisions per-run environments onto: probe a candidate connection without saving it, or bind one. The credential is write-only, so a read reports which secret keys are stored and never their values. */
  readonly environments: EnvironmentsResource
  /** The models a run in this workspace could actually dispatch to, and why an unavailable one is unavailable: unconfigured, or refused by the account model-family policy. Those two need opposite fixes. */
  readonly models: ModelsResource
  /** The workspace's source-control connection: which account it talks to, how it authenticates, and whether it may create repositories and write workflow files. Both permissions are enforced by the provider at push time, so reading them beats discovering one missing halfway through an automated setup. */
  readonly vcs: VcsResource
  /** What this workspace does to a task's LINKED tracker issue as its pull request progresses: comment when it opens, comment and close the issue when it merges, and post a headless run's parked review findings so the reporter can answer where they filed. The write MERGES, so turning one action on leaves the other two as they were. It is the writeback half of the workspace's tracker configuration; the filing selection (which tracker a tech-debt ticket is raised on) is not published yet. */
  readonly tracker: TrackerResource
  /** The risk policies a task can pin, including which is the workspace default: what decides whether a run can land its pull request without a person, and how many attempts its CI fixer, requirement rounds and release watch are given. Broader than merging, which is why it is not called a merge preset. */
  readonly riskPolicies: RiskPoliciesResource
  /** The model presets a task can pin, including which is the workspace default: what decides which model each agent step runs on, and so what a run costs. Availability is not repeated here; join `baseModelId` against the models group, which keeps unconfigured and policy-refused apart. */
  readonly modelPresets: ModelPresetsResource
  /** The workspace's outbound endpoints: register, inspect or remove the receivers that notifications, run-lifecycle events and health alerts are pushed to. The unnamed calls address the `default` endpoint; the named ones let an integration enroll its own receiver, with its own signing secret and filters, beside whatever else is registered. */
  readonly webhook: WebhookResource
  /** The workspace's money, two ways: the billing period's metered budget position with the per-model breakdown behind it, and spend over a window sliced by the dimension a budget is kept against (a repository, a tracker ticket, one run). */
  readonly usage: UsageResource
  /** What the calling key is and what it may do — the self-check an integration runs at startup. */
  readonly me: MeResource
  /** Every way a run stops for a person: approval gates, review and brainstorm loops, forks, judge verdicts, PR review findings, the human-verdict gates, follow-up triage and the interview gates. */
  readonly decisions: DecisionsResource
  /** A run's recorded telemetry: LLM calls, the context each agent was given, the tool calls it made, infra logs, and the whole model-activity bundle as one document. */
  readonly debug: DebugResource
  /** What a run proved: the engine's verification report, the outcome summary behind it, and the artifacts it captured, bytes included. */
  readonly evidence: EvidenceResource
  /** The evidence behind the auto-merge policy: what kind of change each merged run made, what the merger scored it, what happened to the pull request, and how much review a human actually spent, plus the per-class rollups that justify widening a rule. Reading takes a `read` key and recording an effort tag a `write` one: neither merges anything. */
  readonly mergeRecords: MergeRecordsResource
  /** The workspace's own API keys: provision one headlessly, list them, revoke one (and what it minted). */
  readonly keys: KeysResource

  protected constructor(transport: Transport) {
    this.jobs = new JobsResource(transport)
    this.services = new ServicesResource(transport)
    this.spec = new SpecResource(transport)
    this.repos = new ReposResource(transport)
    this.tasks = new TasksResource(transport)
    this.pipelines = new PipelinesResource(transport)
    this.taskTypes = new TaskTypesResource(transport)
    this.notifications = new NotificationsResource(transport)
    this.environments = new EnvironmentsResource(transport)
    this.models = new ModelsResource(transport)
    this.vcs = new VcsResource(transport)
    this.tracker = new TrackerResource(transport)
    this.riskPolicies = new RiskPoliciesResource(transport)
    this.modelPresets = new ModelPresetsResource(transport)
    this.webhook = new WebhookResource(transport)
    this.usage = new UsageResource(transport)
    this.me = new MeResource(transport)
    this.decisions = new DecisionsResource(transport)
    this.debug = new DebugResource(transport)
    this.evidence = new EvidenceResource(transport)
    this.mergeRecords = new MergeRecordsResource(transport)
    this.keys = new KeysResource(transport)
  }
}
